import {ToolRegistry} from './registry.js';

describe('ToolRegistry schema validation', () => {
  it('rejects input missing a required property without calling executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;

    registry.register(
      {
        name: 'test_tool',
        description: 'Test tool',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'result';
      }
    );

    const response = await registry.execute('test_tool', {});

    expect({
      executorCalls,
      containsLocation: response.result.includes('location'),
      containsRequired: /required/i.test(response.result),
    }).toEqual({
      executorCalls: 0,
      containsLocation: true,
      containsRequired: true,
    });
  });

  it('passes valid input with unlisted extra properties through to executor unchanged', async () => {
    const registry = new ToolRegistry();
    let capturedInput: Record<string, unknown> | undefined;

    registry.register(
      {
        name: 'test_tool',
        description: 'Test tool',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async input => {
        capturedInput = input;
        return 'result';
      }
    );

    const input = {location: 'Paris', extra: 'value', nested: {key: 'data'}};
    const response = await registry.execute('test_tool', input);

    expect({
      capturedInput,
      result: response.result,
    }).toEqual({
      capturedInput: input,
      result: 'result',
    });
  });

  it('throws Unknown tool error for unregistered tool name', async () => {
    const registry = new ToolRegistry();

    await expect(registry.execute('nonexistent_tool', {})).rejects.toThrow('Unknown tool: nonexistent_tool');
  });
});

